package com.nexleechutility;

import net.runelite.api.gameval.NpcID;

/**
 * Nex's four minions, in the fixed order they become attackable during a kill.
 * Each minion is preceded by a "warning" line (Nex invokes the element) and then
 * an "activation" line ("&lt;name&gt;, don't fail me!") at which point it can be attacked.
 * Chat lines are stored lowercased/normalised to match {@link NexLeechUtilityPlugin#normalize}.
 */
public enum Minion
{
	// thresholdPercent = Nex's HP% at which this minion becomes attackable. The trigger is HP-gated
	// (DPS-independent), confirmed in-game and on the wiki: Nex has 3400 HP in 20% phase bands, and
	// each minion goes live as she crosses its threshold. The seconds estimate is NOT a fixed
	// value - it's derived live from Nex's current HP and her measured drain rate, so it adapts to
	// team DPS. The "<minion>, don't fail me!" chat line is the frame-exact confirmation.
	FUMUS("Fumus", NpcID.NEX_SMOKEMAGE, "fill my soul with smoke!", "fumus, don't fail me!", 80),
	UMBRA("Umbra", NpcID.NEX_SHADOWMAGE, "darken my shadow!", "umbra, don't fail me!", 60),
	CRUOR("Cruor", NpcID.NEX_BLOODMAGE, "flood my lungs with blood!", "cruor, don't fail me!", 40),
	GLACIES("Glacies", NpcID.NEX_ICEMAGE, "infuse me with the power of ice!", "glacies, don't fail me!", 20);

	private final String displayName;
	private final int npcId;
	private final String warningLine;
	private final String activationLine;
	private final int thresholdPercent;

	Minion(String displayName, int npcId, String warningLine, String activationLine, int thresholdPercent)
	{
		this.displayName = displayName;
		this.npcId = npcId;
		this.warningLine = warningLine;
		this.activationLine = activationLine;
		this.thresholdPercent = thresholdPercent;
	}

	public int getNpcId()
	{
		return npcId;
	}

	public int getThresholdPercent()
	{
		return thresholdPercent;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}

	/** True if this minion is at or after {@code start} in the fixed rotation. */
	public boolean atOrAfter(Minion start)
	{
		return ordinal() >= start.ordinal();
	}

	public static Minion byNpcId(int id)
	{
		for (Minion m : values())
		{
			if (m.npcId == id)
			{
				return m;
			}
		}
		return null;
	}

	public static Minion byWarningLine(String normalizedMessage)
	{
		for (Minion m : values())
		{
			if (m.warningLine.equals(normalizedMessage))
			{
				return m;
			}
		}
		return null;
	}

	public static Minion byActivationLine(String normalizedMessage)
	{
		for (Minion m : values())
		{
			if (m.activationLine.equals(normalizedMessage))
			{
				return m;
			}
		}
		return null;
	}
}

package com.nexleechutility;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class NexLeechOverlay extends OverlayPanel
{
	private final NexLeechUtilityPlugin plugin;
	private final NexLeechUtilityConfig config;

	@Inject
	NexLeechOverlay(NexLeechUtilityPlugin plugin, NexLeechUtilityConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// Keep showing the last kill's stats after the fight ends, optionally expiring
		// after the configured timeout (0 = keep until the next kill).
		boolean haveStatsToShow = plugin.isInFight() || (plugin.isEverFought() && !timedOut());
		if (!config.showDamageOverlay() || !haveStatsToShow)
		{
			return null;
		}

		int damage = plugin.getOwnDamageThisKill();
		boolean qualified = damage >= NexLeechUtilityPlugin.MINIMUM_LEECH_DAMAGE;
		double contribution = plugin.getContributionPercent();

		// e.g. "25 (0.5%)" - green once qualified, red until then.
		String damageText = String.format("%d (%.1f%%)", damage, contribution);

		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Nex Leech")
			.color(Color.ORANGE)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Damage:")
			.right(damageText)
			.rightColor(qualified ? Color.GREEN : Color.RED)
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Drop Rate:")
			.right(fraction(plugin.getUniqueChanceRoll()))
			.build());

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Players:")
			.right(String.valueOf(plugin.getPlayerCount()))
			.build());

		return super.render(graphics);
	}

	private boolean timedOut()
	{
		int timeoutSeconds = config.damageOverlayTimeout();
		if (timeoutSeconds <= 0)
		{
			return false;
		}
		return System.currentTimeMillis() - plugin.getLastFightEndMillis() > timeoutSeconds * 1000L;
	}

	private static String fraction(int value)
	{
		return value <= 0 ? "N/A" : "1/" + value;
	}
}

package com.nexleechutility;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class NexLeechScreenFlashOverlay extends Overlay
{
	private static final Font FLASH_FONT = FontManager.getRunescapeBoldFont().deriveFont(48f);

	private final Client client;
	private final NexLeechUtilityPlugin plugin;
	private final NexLeechUtilityConfig config;

	@Inject
	NexLeechScreenFlashOverlay(Client client, NexLeechUtilityPlugin plugin, NexLeechUtilityConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		NexLeechUtilityPlugin.FlashType flash = plugin.getActiveFlash();
		if (flash == null)
		{
			return null;
		}

		boolean isHpFlash = flash == NexLeechUtilityPlugin.FlashType.HP;
		Color tintColor = isHpFlash ? config.lowHpFlashColor() : config.lowPrayerFlashColor();
		String text = isHpFlash ? config.lowHpFlashText() : config.lowPrayerFlashText();

		int width = client.getCanvasWidth();
		int height = client.getCanvasHeight();

		// Screen tint at the configured opacity; stays up while the flash is active.
		graphics.setColor(tintColor);
		graphics.fillRect(0, 0, width, height);

		boolean hasText = text != null && !text.isEmpty();
		if (hasText)
		{
			graphics.setFont(FLASH_FONT);
			FontMetrics metrics = graphics.getFontMetrics();
			int x = (width - metrics.stringWidth(text)) / 2;
			int y = height / 2 + metrics.getAscent() / 2;

			graphics.setColor(Color.BLACK);
			graphics.drawString(text, x + 2, y + 2);
			graphics.setColor(Color.WHITE);
			graphics.drawString(text, x, y);
		}

		return null;
	}
}

